trial.program_source:
def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set(); regs=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or grid[r][c]==5: continue
   seen.add((r,c)); q=[(r,c)]; edge=False
   for y,x in q:
    if y in (0,h-1) or x in (0,w-1): edge=True
    for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]!=5:
      seen.add((a,b)); q.append((a,b))
   if not edge: regs.append(q)
 regs.sort(key=lambda q:(min(x for y,x in q),min(y for y,x in q)))
 for i,q in enumerate(regs):
  color=[2,4,3][i%3]
  for y,x in q: out[y][x]=color
 return out

